import java.util.*;
import org.jfree.chart.util.PublicCloneable;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class GrayPaintScale_getPaint_TriageGen0Test {







    @Test
    public void testGetPaint_BelowLowerBound() {
        double lower = 10.0;
        double upper = 20.0;
        GrayPaintScale scale = new GrayPaintScale(lower, upper);

        // Test value below lower bound (should be clamped to lower bound)
        // Math.max(5.0, 10.0) -> 10.0 -> Color(0,0,0)
        Paint paint = scale.getPaint(5.0);
        assertEquals(new Color(0, 0, 0), paint);
    }




}

package org.jfree.chart.renderer;

import java.awt.Color;
import java.awt.Paint;
import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.jfree.chart.util.PublicCloneable;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class GrayPaintScale_getPaint_TriageGen0Test {









    @Test
    public void testGetPaint_AboveUpperBound() {
        double lower = 0.0;
        double upper = 100.0;
        GrayPaintScale scale = new GrayPaintScale(lower, upper);

        // Test value above upper bound (should result in intensity > 255, but Color constructor handles it or truncates)
        // Based on the logic: (150-0)/(100-0) * 255 = 1.5 * 255 = 382.5
        // Note: java.awt.Color(int r, int g, int b) clamps values to 0-255 internally
        Paint paint = scale.getPaint(150.0);
        assertEquals(new Color(255, 255, 255), paint);
    }


}

package org.jfree.chart.renderer;

import java.awt.Color;
