import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class GrayPaintScale_getPaint_TriageGen0Test {











    @Test
    public void testGetPaint_NegativeBounds() {
        double lower = -100.0;
        double upper = 0.0;
        GrayPaintScale scale = new GrayPaintScale(lower, upper);

        // Test value at midpoint of negative range
        // (-50 - (-100)) / (0 - (-100)) * 255 = 50 / 100 * 255 = 127.5 -> 127
        Paint paint = scale.getPaint(-50.0);
        assertEquals(new Color(127, 127, 127), paint);
    }
}
